ruleSearch.bookList:
@js:(function(){
var out=[];
var re=/<li class="list-comic" data-key="(\d+)"><a class="image-link"\s+href="([^"]+)"\s+title="([^"]+)"><img src="([^"]+)"[^>]*><\/a>\s*<p><a href="[^"]*"[^>]*>([^<]+)<\/a><\/p>\s*<p class="auth"><a href="[^"]*">([^<]*)<\/a><\/p>\s*<p class="newPage">([^<]*)<\/p>/g;
var m;
while((m=re.exec(result))){
  var cover=m[4];
  if(cover.indexOf('http')<0)cover='https://www.ykmh.net'+(cover.charAt(0)==='/'?cover:'/'+cover);
  var u=m[2];
  if(u.indexOf('http')<0)u='https://www.ykmh.net'+(u.charAt(0)==='/'?u:'/'+u);
  out.push({name:m[3],bookUrl:u,coverUrl:cover,author:m[6]||'',lastChapter:m[7]||''});
}
return out;})()

ruleToc.chapterList:
@js:(function(){
var out=[];var seen={};
var groupRe=/<div class="comic-chapters">[\s\S]*?<span class="Title">([^<]+)<\/span>[\s\S]*?<ul id="chapter-list-\d+"[^>]*>([\s\S]*?)<\/ul>/g;
var gm;
while((gm=groupRe.exec(result))){
  var gname=gm[1].trim();
  var chRe=/<li>\s*<a href="([^"]+)"[^>]*>\s*<span>([^<]+)<\/span>\s*<\/a>\s*<\/li>/g;
  var m;
  while((m=chRe.exec(gm[2]))){
    var u=m[1];if(u.indexOf('http')<0)u='https://m.ykmh.net'+(u.charAt(0)==='/'?u:'/'+u);
    var n=m[2].trim();if(gname!=='连载列表')n='['+gname+'] '+n;
    if(!seen[u]){seen[u]=1;out.push({name:n,url:u});}
  }
}
if(out.length===0){
  var allRe=/<li>\s*<a href="([^"]+)"[^>]*>\s*<span>([^<]+)<\/span>\s*<\/a>\s*<\/li>/g;
  var m2;
  while((m2=allRe.exec(result))){
    var u2=m2[1];if(u2.indexOf('http')<0)u2='https://m.ykmh.net'+(u2.charAt(0)==='/'?u2:'/'+u2);
    if(!seen[u2]){seen[u2]=1;out.push({name:m2[2].trim(),url:u2});}
  }
}
return out;})()

ruleContent.content:
@js:(function(){
var out=[];var seen={};
var sm=result.match(/var\s+chapterImages\s*=\s*(\[.*?\]);/);
if(sm){
  try{
    var list=JSON.parse(sm[1]);
    for(var i=0;i<list.length;i++){
      var u=list[i];
      if(u.indexOf('http')<0)u='https://m.ykmh.net'+(u.charAt(0)==='/'?u:'/'+u);
      if(!seen[u]){seen[u]=1;out.push('<img src="'+u+'">');}
    }
  }catch(e){}
}
if(out.length===0){
  var re=/<img[^>]+src="([^"]+)"[^>]*>/g;
  var m;
  while((m=re.exec(result))){
    var u=m[1];
    if(u.indexOf('cover')>=0||u.indexOf('avatar')>=0||u.indexOf('logo')>=0||u.indexOf('icon')>=0||u.indexOf('banner')>=0)continue;
    if(u.indexOf('http')<0)u='https://m.ykmh.net'+(u.charAt(0)==='/'?u:'/'+u);
    if(!seen[u]){seen[u]=1;out.push('<img src="'+u+'">');}
  }
}
return out.join('\n');})()
